def make_train_step_fn(model, loss_fn, optimizer):
 def train_step(x, y):
 model.train()
 yhat = model(x)
 loss = loss_fn(yhat, y)
 loss.backward()
 optimizer.step()
 optimizer.zero_grad()
 return loss.item()
 return train_step

# 定义验证步骤函数
